import json

def solve(data):
    # Check for empty strings
    if data['a'] == "" and data['b'] == "":
        return 0

    def edit_distance(s1, s2):
        m = len(s1)
        n = len(s2)

        # Create a 2D array to store results of subproblems
        dp = [[0] * (n+1) for _ in range(m+1)]

        # Fill the table
        for i in range(1, m+1):
            for j in range(1, n+1):
                if s1[i-1] == s2[j-1]:
                    dp[i][j] = dp[i-1][j-1]
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1

        # The result is in the bottom-right corner of the table
        return dp[m][n]

    # Calculate edit distance between input strings
    return edit_distance(data['a'], data['b'])

# Example usage
print(json.dumps(solve({"a": "", "b": ""})))  # Output: 0
print(json.dumps(solve({"a": "kitten", "b": "sitting"})))  # Output: 3
print(json.dumps(solve({"a": "abc", "b": ""})))  # Output: 3
print(json.dumps(solve({"a": "a", "b": "b"})))  # Output: 1

